CREATE TABLE finance_requests (
 id BINARY(16) PRIMARY KEY, organization_id BINARY(16) NOT NULL, source_domain VARCHAR(60) NOT NULL, source_record_id VARCHAR(160) NOT NULL,
 request_type VARCHAR(60) NOT NULL, amount DECIMAL(19,2) NOT NULL, currency VARCHAR(3) NOT NULL, reason VARCHAR(2000) NOT NULL, notes VARCHAR(4000),
 supporting_reference VARCHAR(500), due_date DATE, requester_id BINARY(16) NOT NULL, status VARCHAR(20) NOT NULL, reviewer_id BINARY(16), reviewed_at TIMESTAMP NULL,
 rejection_reason VARCHAR(2000), resulting_operation_id BINARY(16), created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL,
 INDEX idx_finance_request_org_status (organization_id,status), INDEX idx_finance_request_source (organization_id,source_domain,source_record_id),
 FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE TABLE finance_request_attachments (id BINARY(16) PRIMARY KEY, finance_request_id BINARY(16) NOT NULL, storage_reference VARCHAR(1000) NOT NULL, filename VARCHAR(255) NOT NULL, content_type VARCHAR(127) NOT NULL, uploaded_by BINARY(16) NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, INDEX idx_finance_request_attachment_request (finance_request_id), FOREIGN KEY (finance_request_id) REFERENCES finance_requests(id));
CREATE TABLE finance_request_events (id BINARY(16) PRIMARY KEY, finance_request_id BINARY(16) NOT NULL, prior_status VARCHAR(20), new_status VARCHAR(20) NOT NULL, action VARCHAR(60) NOT NULL, actor_id BINARY(16) NOT NULL, notes VARCHAR(2000), occurred_at TIMESTAMP NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, INDEX idx_finance_request_event_request_created (finance_request_id,created_at), FOREIGN KEY (finance_request_id) REFERENCES finance_requests(id));
CREATE TABLE finance_accounts (id BINARY(16) PRIMARY KEY, organization_id BINARY(16) NOT NULL, type VARCHAR(20) NOT NULL, name VARCHAR(160) NOT NULL, location_id BINARY(16), currency VARCHAR(3) NOT NULL, status VARCHAR(20) NOT NULL, assigned_employee_id BINARY(16), created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, UNIQUE KEY uk_finance_account_org_name (organization_id,name), INDEX idx_finance_account_org_type_status (organization_id,type,status), FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE TABLE finance_operations (id BINARY(16) PRIMARY KEY, organization_id BINARY(16) NOT NULL, type VARCHAR(30) NOT NULL, source_account_id BINARY(16), destination_account_id BINARY(16), amount DECIMAL(19,2) NOT NULL, currency VARCHAR(3) NOT NULL, reference VARCHAR(160), description VARCHAR(2000), notes VARCHAR(4000), finance_request_id BINARY(16), created_by BINARY(16) NOT NULL, status VARCHAR(20) NOT NULL, executed_at TIMESTAMP NULL, confirmed_at TIMESTAMP NULL, idempotency_key VARCHAR(128) NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, UNIQUE KEY uk_finance_operation_idempotency (organization_id,idempotency_key), INDEX idx_finance_operation_org_status (organization_id,status), FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE TABLE finance_operation_attachments (id BINARY(16) PRIMARY KEY, operation_id BINARY(16) NOT NULL, storage_reference VARCHAR(1000) NOT NULL, filename VARCHAR(255) NOT NULL, content_type VARCHAR(127) NOT NULL, uploaded_by BINARY(16) NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, INDEX idx_finance_operation_attachment_operation (operation_id), FOREIGN KEY (operation_id) REFERENCES finance_operations(id));
CREATE TABLE finance_ledger_entries (id BINARY(16) PRIMARY KEY, organization_id BINARY(16) NOT NULL, operation_id BINARY(16) NOT NULL, account_id BINARY(16) NOT NULL, direction VARCHAR(10) NOT NULL, amount DECIMAL(19,2) NOT NULL, currency VARCHAR(3) NOT NULL, posted_at TIMESTAMP NOT NULL, reference VARCHAR(160), created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, INDEX idx_finance_ledger_account_posted (account_id,posted_at), INDEX idx_finance_ledger_operation (operation_id), FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE TABLE finance_transfer_confirmations (id BINARY(16) PRIMARY KEY, organization_id BINARY(16) NOT NULL, operation_id BINARY(16) NOT NULL, sender_id BINARY(16), receiver_id BINARY(16), qr_token VARCHAR(128) NOT NULL, qr_reference VARCHAR(160), status VARCHAR(20) NOT NULL, verified_at TIMESTAMP NULL, confirmed_at TIMESTAMP NULL, expires_at TIMESTAMP NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, UNIQUE KEY uk_finance_transfer_confirmation_operation (operation_id), INDEX idx_finance_transfer_confirmation_token (qr_token), FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE TABLE finance_payroll_payments (id BINARY(16) PRIMARY KEY, organization_id BINARY(16) NOT NULL, payroll_id BINARY(16) NOT NULL, employee_id BINARY(16) NOT NULL, amount DECIMAL(19,2) NOT NULL, currency VARCHAR(3) NOT NULL, source_account_id BINARY(16) NOT NULL, operation_id BINARY(16) NOT NULL, receiver_verification_status VARCHAR(20), finance_actor_id BINARY(16) NOT NULL, paid_at TIMESTAMP NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, UNIQUE KEY uk_finance_payroll_payment_operation (operation_id), INDEX idx_finance_payroll_payment_payroll (organization_id,payroll_id), FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE TABLE finance_chart_of_accounts (id BINARY(16) PRIMARY KEY, organization_id BINARY(16) NOT NULL, code VARCHAR(32) NOT NULL, name VARCHAR(160) NOT NULL, account_type VARCHAR(32) NOT NULL, active BOOLEAN NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, UNIQUE KEY uk_finance_coa_org_code (organization_id,code), FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE TABLE finance_journal_entries (id BINARY(16) PRIMARY KEY, organization_id BINARY(16) NOT NULL, reference VARCHAR(160) NOT NULL, description VARCHAR(2000), posted BOOLEAN NOT NULL, posted_at TIMESTAMP NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, INDEX idx_finance_journal_org_posted (organization_id,posted_at), FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE TABLE finance_journal_entry_lines (id BINARY(16) PRIMARY KEY, journal_entry_id BINARY(16) NOT NULL, chart_account_id BINARY(16) NOT NULL, debit DECIMAL(19,2) NOT NULL, credit DECIMAL(19,2) NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, INDEX idx_finance_journal_line_entry (journal_entry_id), FOREIGN KEY (journal_entry_id) REFERENCES finance_journal_entries(id), FOREIGN KEY (chart_account_id) REFERENCES finance_chart_of_accounts(id));
